// One item per PDF attachment: an email with three invoices gives three rows.
// Other attachments (logos, signatures, spreadsheets) are skipped.
const results = [];

for (const [index, item] of $input.all().entries()) {
  const email = item.json;
  const sender = email.from?.value?.[0];

  for (const [key, file] of Object.entries(item.binary ?? {})) {
    const isPdf = file.mimeType === 'application/pdf' || /\.pdf$/i.test(file.fileName ?? '');
    if (!isPdf) continue;

    results.push({
      json: {
        gmail_message_id: email.id,
        email_from: sender?.address ?? email.from?.text ?? '',
        email_subject: email.subject ?? '',
        received_at: new Date(email.date ?? Date.now()).toISOString(),
        file_name: file.fileName ?? `${key}.pdf`,
      },
      binary: { data: file },
      pairedItem: { item: index },
    });
  }
}

return results;

// The request for OpenAI: the PDF text, instructions, and a JSON schema the
// answer must follow. Strict mode means every field is always present
// (null when it isn't on the invoice), so the next node never guesses.
const MAX_CHARS = 30000;

const SYSTEM = `You extract data from supplier invoices for bookkeeping.
The text was extracted from a PDF, so lines and spacing may be broken.

Rules:
- The supplier is the seller (Постачальник, Verkäufer, Lieferant), never the buyer (Покупець, Kunde).
- supplier_tax_id: the seller's ЄДРПОУ, РНОКПП or VAT id as printed, without spaces.
- Dates as YYYY-MM-DD, whatever the format on the invoice (03.11.2026, "3 листопада 2026 р.").
- Amounts as plain numbers: 1.574,00 € -> 1574.00, 10 000,00 -> 10000.00.
- currency as an ISO 4217 code: грн, ₴ -> UAH; € -> EUR.
- vat_rate in percent. When the invoice says there is no VAT (Без ПДВ, VAT exempt), vat_rate and vat_amount are 0.
- Copy the totals exactly as printed, even if they don't add up. Never correct them.
- Use null for anything that is not on the document.
- confidence (0 to 1): how sure you are that every field is right. Lower it when the text is garbled, fields are missing, or the document may not be an invoice.`;

const nullable = (type) => ({ type: [type, 'null'] });

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: [
    'supplier_name', 'supplier_tax_id', 'invoice_number', 'invoice_date', 'due_date',
    'currency', 'net_amount', 'vat_rate', 'vat_amount', 'total_amount', 'confidence',
  ],
  properties: {
    supplier_name: nullable('string'),
    supplier_tax_id: nullable('string'),
    invoice_number: nullable('string'),
    invoice_date: { ...nullable('string'), description: 'YYYY-MM-DD' },
    due_date: { ...nullable('string'), description: 'YYYY-MM-DD' },
    currency: { ...nullable('string'), description: 'ISO 4217, e.g. UAH, EUR' },
    net_amount: { ...nullable('number'), description: 'Total without VAT' },
    vat_rate: { ...nullable('number'), description: 'Percent, 0 when VAT-exempt' },
    vat_amount: nullable('number'),
    total_amount: { ...nullable('number'), description: 'Amount due, as printed' },
    confidence: { type: 'number' },
  },
};

const fileName = $('Split PDF attachments').item.json.file_name;
const text = String($json.text ?? '').trim().slice(0, MAX_CHARS);

return {
  json: {
    request: {
      model: $env.INVOICE_OPENAI_MODEL || 'gpt-5-mini',
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: `File: ${fileName}\n\n${text}` },
      ],
      response_format: {
        type: 'json_schema',
        json_schema: { name: 'invoice', strict: true, schema: SCHEMA },
      },
    },
  },
};

// OpenAI's answer, cleaned up into one row of the Invoices sheet, together
// with where the invoice came from.
const source = $('Split PDF attachments').item.json;
const message = $json.choices?.[0]?.message;

if (message?.refusal) {
  throw new Error(`OpenAI refused to read ${source.file_name}: ${message.refusal}`);
}
if (!message?.content) {
  throw new Error(`OpenAI returned no answer for ${source.file_name}`);
}

const data = JSON.parse(message.content);

const text = (value) => (typeof value === 'string' && value.trim() ? value.trim() : null);
const amount = (value) =>
  typeof value === 'number' && Number.isFinite(value) ? Math.round(value * 100) / 100 : null;
const isoDate = (value) => {
  const date = text(value);
  if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return null;
  // 2026-02-30 matches the pattern but isn't a date.
  return new Date(`${date}T00:00:00Z`).toISOString().startsWith(date) ? date : null;
};
const confidence = amount(data.confidence);

return {
  json: {
    received_at: source.received_at,
    supplier_name: text(data.supplier_name),
    supplier_tax_id: text(data.supplier_tax_id)?.replace(/\s+/g, '') ?? null,
    invoice_number: text(data.invoice_number),
    invoice_date: isoDate(data.invoice_date),
    due_date: isoDate(data.due_date),
    currency: text(data.currency)?.toUpperCase() ?? null,
    net_amount: amount(data.net_amount),
    vat_rate: amount(data.vat_rate),
    vat_amount: amount(data.vat_amount),
    total_amount: amount(data.total_amount),
    confidence: confidence === null ? null : Math.min(1, Math.max(0, confidence)),
    file_name: source.file_name,
    email_from: source.email_from,
    email_subject: source.email_subject,
    email_link: `https://mail.google.com/mail/u/0/#all/${source.gmail_message_id}`,
    gmail_message_id: source.gmail_message_id,
  },
};

// Decide, for every invoice, whether it can go straight into the books.
// Anything that fails a check goes to the Review tab with the reasons.
// Rounding allowed between amounts, in cents.
const TOLERANCE_CENTS = 2;
const parsedConfidence = Number.parseFloat($env.INVOICE_MIN_CONFIDENCE);
const MIN_CONFIDENCE = Number.isFinite(parsedConfidence) ? parsedConfidence : 0.8;
const TIME_ZONE = $env.GENERIC_TIMEZONE || 'Europe/Kyiv';

const REQUIRED = {
  supplier_name: 'supplier',
  invoice_number: 'invoice number',
  invoice_date: 'invoice date',
  currency: 'currency',
  net_amount: 'net amount',
  vat_amount: 'VAT amount',
  total_amount: 'total',
};

// 10140 -> "10 140,00"
const money = (value) => {
  const [whole, cents] = Math.abs(value).toFixed(2).split('.');
  return `${value < 0 ? '-' : ''}${whole.replace(/\B(?=(\d{3})+(?!\d))/g, ' ')},${cents}`;
};
// Compare in whole cents: 12000.02 - 12000 is 0.0200000000004 in floating point.
const differs = (a, b) => Math.abs(Math.round(a * 100) - Math.round(b * 100)) > TOLERANCE_CENTS;

// Same supplier and number = same invoice. The tax id is the reliable part;
// without one, fall back to the name.
const key = (row) => {
  const supplier = String(row.supplier_tax_id || row.supplier_name || '').replace(/\s+/g, '').toLowerCase();
  const number = String(row.invoice_number ?? '').replace(/\s+/g, '').toLowerCase();
  return supplier && number ? `${supplier}|${number}` : null;
};

// Rows already in the Invoices tab. With an empty sheet, the read node
// still sends one empty item.
const seen = new Set($input.all().map((item) => key(item.json)).filter(Boolean));
const today = new Date().toLocaleDateString('sv-SE', { timeZone: TIME_ZONE });

return $('Parse invoice').all().map(({ json: invoice }) => {
  const reasons = [];
  const details = [];

  const missing = Object.entries(REQUIRED)
    .filter(([field]) => invoice[field] === null || invoice[field] === undefined)
    .map(([, label]) => label);
  if (missing.length) {
    reasons.push('missing_fields');
    details.push(`Missing: ${missing.join(', ')}`);
  }

  const { net_amount: net, vat_amount: vat, vat_rate: rate, total_amount: total } = invoice;
  if (net !== null && vat !== null && total !== null) {
    const mismatches = [];
    if (differs(net + vat, total)) {
      mismatches.push(`net + VAT is ${money(net + vat)}, the total says ${money(total)}`);
    }
    if (rate !== null && differs((net * rate) / 100, vat)) {
      mismatches.push(`${rate}% VAT on ${money(net)} is ${money((net * rate) / 100)}, the invoice says ${money(vat)}`);
    }
    if (mismatches.length) {
      reasons.push('amounts_mismatch');
      details.push(`Amounts don't add up: ${mismatches.join('; ')}`);
    }
  }

  const dateProblems = [];
  if (invoice.invoice_date && invoice.invoice_date > today) {
    dateProblems.push(`invoice date ${invoice.invoice_date} is in the future`);
  }
  if (invoice.invoice_date && invoice.due_date && invoice.due_date < invoice.invoice_date) {
    dateProblems.push(`due date ${invoice.due_date} is before the invoice date`);
  }
  if (dateProblems.length) {
    reasons.push('invalid_date');
    details.push(`Dates: ${dateProblems.join('; ')}`);
  }

  if (invoice.confidence === null || invoice.confidence < MIN_CONFIDENCE) {
    reasons.push('low_confidence');
    const percent = invoice.confidence === null ? 'unknown' : `${Math.round(invoice.confidence * 100)}%`;
    details.push(`AI confidence ${percent}, below ${Math.round(MIN_CONFIDENCE * 100)}%`);
  }

  const invoiceKey = key(invoice);
  if (invoiceKey && seen.has(invoiceKey)) {
    reasons.push('duplicate');
    details.push(`Already in the books: ${invoice.invoice_number} from ${invoice.supplier_name}`);
  }
  // Two copies in one batch: the first goes through, the second is a duplicate.
  if (invoiceKey) seen.add(invoiceKey);

  return { json: { ...invoice, review_reasons: reasons, review_details: details.join('. ') } };
});

// One row of the Invoices tab: exactly its columns, in order.
const COLUMNS = [
  'received_at', 'supplier_name', 'supplier_tax_id', 'invoice_number', 'invoice_date',
  'due_date', 'currency', 'net_amount', 'vat_rate', 'vat_amount', 'total_amount',
  'confidence', 'file_name', 'email_from', 'email_subject', 'email_link', 'gmail_message_id',
];

return { json: Object.fromEntries(COLUMNS.map((column) => [column, $json[column] ?? null])) };

// The Slack message for a filed invoice.
const invoice = $('Ledger row').item.json;

// Slack treats &, < and > as markup.
const escape = (value) =>
  String(value ?? '—').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// 12000 -> "12 000,00"
const money = (value) => {
  if (value === null || value === undefined) return '—';
  const [whole, cents] = Math.abs(value).toFixed(2).split('.');
  const sign = value < 0 ? '-' : '';
  return `${sign}${whole.replace(/\B(?=(\d{3})+(?!\d))/g, ' ')},${cents}`;
};

const currency = escape(invoice.currency ?? '');
const vat = invoice.vat_rate
  ? `VAT ${invoice.vat_rate}%: ${money(invoice.vat_amount)} ${currency}`
  : 'No VAT';

const lines = [
  `:receipt: *New invoice from ${escape(invoice.supplier_name)}*`,
  `*${money(invoice.total_amount)} ${currency}* · No. ${escape(invoice.invoice_number)} · dated ${escape(invoice.invoice_date)} · due ${escape(invoice.due_date)}`,
  `${vat} · ${escape(invoice.file_name)}`,
  `<${invoice.email_link}|Open the email>`,
];

return { json: { text: lines.join('\n') } };

// A PDF the workflow couldn't read: no text in it (a scan), or reading or
// extracting it failed even after retries. It goes to review with the reason;
// the rest of the batch carries on.
const source = $('Split PDF attachments').item.json;
const error = $json.error;

const failed = error !== undefined;
const raw = typeof error === 'string' ? error : (error?.message ?? 'unknown error');
// API errors arrive as `500 - "{\"error\":{\"message\":\"...\"}}"`: keep the readable part.
const status = /^(\d{3}) - /.exec(raw)?.[1];
const inner = /message\\?"\s*:\s*\\?"([^"\\]+)/.exec(raw)?.[1];
const message = inner ? `${status ? `HTTP ${status}: ` : ''}${inner}` : raw;

return {
  json: {
    received_at: source.received_at,
    supplier_name: null,
    supplier_tax_id: null,
    invoice_number: null,
    invoice_date: null,
    due_date: null,
    currency: null,
    net_amount: null,
    vat_rate: null,
    vat_amount: null,
    total_amount: null,
    confidence: null,
    file_name: source.file_name,
    email_from: source.email_from,
    email_subject: source.email_subject,
    email_link: `https://mail.google.com/mail/u/0/#all/${source.gmail_message_id}`,
    gmail_message_id: source.gmail_message_id,
    review_reasons: [failed ? 'extraction_failed' : 'no_text_layer'],
    review_details: failed
      ? `Couldn't read the invoice: ${message}`
      : 'The PDF has no text layer, probably a scan. Enter it by hand.',
  },
};

// One row of the Review tab: why it's here first, then the same columns as
// the Invoices tab, so a fixed row can be copied straight over.
const COLUMNS = [
  'received_at', 'supplier_name', 'supplier_tax_id', 'invoice_number', 'invoice_date',
  'due_date', 'currency', 'net_amount', 'vat_rate', 'vat_amount', 'total_amount',
  'confidence', 'file_name', 'email_from', 'email_subject', 'email_link', 'gmail_message_id',
];

return {
  json: {
    review_reasons: ($json.review_reasons ?? []).join(', '),
    review_details: $json.review_details ?? '',
    ...Object.fromEntries(COLUMNS.map((column) => [column, $json[column] ?? null])),
  },
};

// The Slack alert for an invoice that needs a person.
const invoice = $('Review row').item.json;

// Slack treats &, < and > as markup.
const escape = (value) =>
  String(value ?? '—').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const sheet = $env.INVOICE_SHEET_ID
  ? ` · <https://docs.google.com/spreadsheets/d/${$env.INVOICE_SHEET_ID}|Open the Review tab>`
  : '';
const from = invoice.supplier_name ? ` from ${escape(invoice.supplier_name)}` : '';

const lines = [
  `:warning: *Invoice needs a review${from}*`,
  `${escape(invoice.file_name)} · ${escape(invoice.email_subject)}`,
  `> ${escape(invoice.review_details)}`,
  `<${invoice.email_link}|Open the email>${sheet}`,
];

return { json: { text: lines.join('\n') } };
